"""Read primary-accepted broker286 data; pinned reviews supply raw analysis."""
import base64,json,struct,tarfile
from pathlib import Path
from primary_controller_evidence import CHECKS,artifact_inventory,canonical,deny_noncore,file_sha,pinned,require,safe_member,sha,tar_members,unit_proof
FORMAT='primary-qualified-broker286-v1'
RECEIPT='ee34b4386af584f3818d89314a590e4d88674fe32f4d78b8c60b32a08bae343a'
FREEZE='9bea16e86efeaf00678036b9a9f2f0d05ebcd9adf204c2c58b0a8a838f884f06'
CORES={'static':'2511208dea53bf380088ca242ea5b26029ebfeceb1794d87fc42fde4df8f22ab','dynamic':'6f0e188ae4509e660fe472ae9d7ba368846c0161184556d5d925d5c527b8e0e2'}
CASES={'partial':'97299c38293066257e1d12da9412ea12b455b776a63beda1811becb16675afef','timeout':'d3577bc5b5da6f2b7c3c4ca7a791e8441600c4696e6eccf0be4e96cc1e08a8c0'}

def load_qualified_broker_run(spec,expected_binary,expected_build):
 require(spec.get('evidence_format')==FORMAT and expected_build in CORES and expected_binary==CORES[expected_build],'broker core differs');deny_noncore(spec,'broker selection');require(spec.get('core_ledger_eligible') is True and spec.get('ledger_scope')=='core','broker scope differs')
 pin=spec['primary_receipt'];require(pin['sha256']==RECEIPT,'broker receipt pin differs');receipt=json.loads(pinned(pin['path'],RECEIPT,'broker receipt'));require(receipt['schema']=='bashos-broker286-primary-acceptance-20261029-v1' and receipt['decision']=='accept-bounded-broker286-r3-r4-observations-for-integration' and receipt['source_freeze_sha256']==FREEZE and receipt['core_ledger_eligible'] is True and receipt['ledger_scope']=='core' and receipt['topic']=='ptybroker/bounded_io_errors','broker authority differs')
 run=spec['receipt_run'];require(run in receipt['runs'],'broker run absent');a=receipt['runs'][run];scenario,build=run.split('-');require(scenario in CASES and build==expected_build,'broker build mismatch');cid='migration-terra-local-pty-broker-256-'+scenario+'-r1';require(a['candidate']==build and a['candidate_sha256']==expected_binary and a['case_id']==cid and a['case_sha256']==CASES[scenario] and a['status']=='PASS' and a['selfchecks_pass']==13 and a['artifact_inventory_verified'] is True and a['payload_source_files_verified']==11 and spec['name']=='broker286-'+run and spec['groups']==['shell'] and spec['ids']==[cid] and not spec.get('exclude_ids'),'broker selection differs')
 root=Path(spec['path']);require(root.is_absolute() and str(root.resolve(strict=True))==a['source_result'],'broker original result differs');core=Path(spec['core_binary_path']);require(core.is_absolute() and file_sha(core)==expected_binary,'broker core differs')
 freeze=spec['source_freeze'];require(freeze['sha256']==FREEZE,'broker freeze pin differs');fp=Path(freeze['path']); f=json.loads(pinned(fp,FREEZE,'broker freeze'));require(f['case_sha256'][cid]==CASES[scenario],'broker freeze case differs'); inventory=json.loads(pinned(fp.parent/'control-files.json',f['inventories']['control-files.json'],'broker source inventory'))
 ready_path=Path(a['review_ready_path']);ready=json.loads(pinned(ready_path,a['review_ready_sha256'],'broker review'));audit=json.loads(pinned(ready_path.parent/'AUDIT.json',ready['audit_sha256'],'broker audit'));require(ready['run']==run and ready['vm_uuid']==a['vm_uuid'] and ready['provenance_sha256']==a['provenance_sha256'] and audit['source_freeze_sha256']==FREEZE and audit['independent_status']=='PASS' and audit['candidate_raw_sha256']==a['raw_case_sha256'] and audit['archive_sha256']==a['evidence_sha256'] and audit['case_sha256']==CASES[scenario] and audit['candidate_sha256']==expected_binary,'broker independent review differs')
 p=json.loads(pinned(root/'provenance.json',a['provenance_sha256'],'broker provenance'));uuid=a['vm_uuid'];require(p['operation']=='broker256-run' and p['status']=='completed' and p['candidate']==build and p['scenario']==scenario and p['vm_uuid']==uuid and p['candidate_sha256']==expected_binary and p['selected_case_ids']==[cid] and p['canonical_case_sha256']==CASES[scenario] and p['root_fixtures_allowed'] is False and p['host_mounts']==[] and p['identity']['marker_matches'] and p['identity']['product_uuid_matches'] and not p['identity']['host_shared_mounts'] and p['runtime_network']['canary_accepted']==0,'broker provenance differs')
 require(p['workspace_core_before']==p['workspace_core_after'] and p['workspace_core_before'].get(str(core))==expected_binary and p['core_before']==p['core_after'],'broker core snapshot differs')
 require(all(p.get(k) is True for k in ('candidate_unchanged','candidate_snapshot_unchanged','prepared_unchanged','controller_unchanged','module_unchanged','suite_unchanged','helper_unchanged','guest_unit_quiescence_proven','compatibility_unit_quiescence_proven','scope_proven','overlay_discarded','evidence_unchanged')),'broker lifecycle or integrity differs');artifact_inventory(root,p);require(not (root/'overlay.qcow2').exists() and file_sha(root/'candidate.snapshot')==expected_binary and file_sha(root/'payload.tar')==a['payload_sha256']==p['payload_sha256'] and file_sha(root/'evidence.tar')==a['evidence_sha256']==p['evidence_validation']['archive_sha256'],'broker archived files differ')
 ns=json.loads(pinned(root/'namespace-proof-208.json',p['namespace_proof_sha256'],'broker namespace'));require(ns==p['namespace_proof']['evaluation'] and ns['token']==ns['dmi_uuid']==uuid and ns['proc_interfaces']==ns['sysfs_interfaces']==['lo'] and all(ns['namespaces'][k]!=p['namespace_proof']['parent'][k] for k in ('mnt','net','pid')),'broker namespace differs')
 with tarfile.open(root/'payload.tar') as tar:
  members=tar_members(tar); source=[m.name for m in members if m.isfile() and (m.name.startswith('harness/') and not m.name.startswith('harness/suites/') or m.name=='loadable-parity/runner.py')];require(len(source)==11 and {m.name for m in members}==set(source)|{'candidate','harness/suites/optional-frozen.json'},'broker payload membership differs');require(sha(safe_member(tar,'candidate'))==expected_binary and sha(safe_member(tar,'harness/suites/optional-frozen.json'))==p['frozen_fixture_sha256'],'broker candidate or fixture payload differs')
  for name in source:
   key=('tests/parity-vm/'+name.removeprefix('harness/')) if name.startswith('harness/') else 'tests/'+name
   require(sha(safe_member(tar,name))==inventory[key],'broker payload source differs: '+name)
  fixture=json.loads(safe_member(tar,'harness/suites/optional-frozen.json'));require(len(fixture['cases'])==1,'broker fixture count differs');case=fixture['cases'][0];require(case['id']==cid and canonical(case)==CASES[scenario],'broker fixture differs')
 summary=json.loads(pinned(root/'guest-summary.json',p['guest_summary_sha256'],'broker summary'));rows=summary['cases'];checks={'selfcheck-'+x for x in CHECKS};selected=[x for x in rows if x['id']==cid and x['group']=='shell'];require(summary['vm_uuid']==uuid and summary['binary_sha256']==expected_binary and summary['selected_case_ids']==[cid] and len(rows)==14 and {x['id'] for x in rows}==checks|{cid} and all(x['status']=='PASS' for x in rows) and len(selected)==1,'broker summary or controls differ')
 with tarfile.open(root/'evidence.tar') as tar:
  tar_members(tar);raw=safe_member(tar,'results/'+cid+'/candidate.json');require(sha(raw)==a['raw_case_sha256'],'broker case data differs');record=json.loads(raw);require(record['status']==0 and record['error'] is None and not record['stray_processes'] and record['setup']['status']==0,'broker raw result differs');diag=record['diagnostics'];rd=base64.b64decode(diag['broker245-report.json']['base64'],validate=True);require(sha(rd)==a['report_sha256'],'broker report differs');report=json.loads(rd);require(report['classification']=='PASS' and report['token']==uuid,'broker report classification differs')
  if scenario=='partial':
   get=lambda n:base64.b64decode(diag[n]['base64'],validate=True);expected=b''.join((i^0x9e3779b97f4a7c15).to_bytes(8,'big') for i in range(2048));frame=get('broker245-peer-frame.bin');blocks=[get('broker245-drain-%d.bin'%i) for i in range(1,5)];require(struct.unpack('=IIIIQ',frame[:24])==(0x42505431,64,16384,0,0) and frame[24:]==expected and get('broker245-expected.bin')==expected and b''.join(blocks)==expected and len(set(blocks))==4 and [len(x) for x in blocks]==[4096]*4 and not report['mismatch'] and not report['extra_hex'],'broker drains differ')
  else: require(all(audit['timings'][x]['result_line']=='RESULT 124 unset' for x in ('default','explicit_250')) and audit['bounds']['maximum'].startswith('MAX 0 attached ') and audit['bounds']['over']=='OVER 2','broker timeout observations differ')
 comp=p['compatibility'];handoff=json.loads(pinned(root/'compat/handoff.json',comp['handoff_sha256'],'broker handoff'));require(handoff==comp['handoff'] and handoff['vm_uuid']==uuid and handoff['status']=='PASS' and handoff['candidate_sha256']==expected_binary and handoff['selected_ids']==[cid],'broker compatibility differs');u='bashos-evaluation-'+uuid[:8]+'.service';v='bashos-optional-'+uuid[:8]+'-reference.service';ev=unit_proof(root/'run.log.unit-proof.json',p['guest_unit_proofs']['run.log.unit-proof.json'],uuid,u,0);sv=unit_proof(root/'compat/run.log.unit-proof.json',p['compatibility_unit_proofs']['run.log.unit-proof.json'],uuid,v,0);require(a['unit_proof_checks']=={'evaluator':ev,'compatibility':sv},'broker unit receipt differs')
 t=json.loads((root/'vm/teardown.json').read_bytes());require(t==p['teardown'] and t['vm_uuid']==uuid and t['clean_poweroff'] and not t['forced_stop'] and t['qemu_exit_status']==0 and t['poweroff_request']==a['poweroff_request'] and t['scope_quiescent'] and t['proof_durable'] and t['cgroup_events']['removed'],'broker VM teardown differs');
 if t['poweroff_request']!=0: require(audit.get('shutdown_console_sha256')==file_sha(root/'vm/console.log') and audit.get('clean_vm_teardown') is True,'broker poweroff requires console evidence')
 return ([{'record':selected[0],'definition':case,'sources':{},'run':spec['name']}],{'name':spec['name'],'groups':['shell'],'selected_records':1,'evidence_format':FORMAT,'primary_receipt_sha256':RECEIPT,'receipt_run':run,'candidate_sha256':expected_binary,'case_definition_sha256':CASES[scenario],'vm_uuid':uuid,'requirement':'ptybroker/bounded_io_errors/'+('r4' if scenario=='partial' else 'r3'),'independent_review_sha256':a['review_ready_sha256'],'provenance_sha256':a['provenance_sha256'],'evidence_sha256':a['evidence_sha256'],'units':{'evaluator':ev,'compatibility':sv},'teardown':t,'overlay_discarded':True})
